INSERT INTO public.coaching_modules (
    id, module_number, title, subtitle, description, youtube_id, tasks, requires_technique_check, created_at, updated_at, etapa, phase, principles, level_label
) VALUES
    ('0b32d170-0100-4fed-bea3-684949428ff5', 1, 'Nastavenie hlavy', 'Vstup do metódy — čo rozhodne o úspechu', 'Mindset. Moje klientky dosahujú úspech jedine ak zvládnu tento vstup. Úprimne 80 % žien skončí po prvom uspokojení s výsledkami, len 20 % žien si zmení život na nepoznanie. Daj seba na 1. miesto v živote a nájdi svoje SILNÉ prečo.', NULL, '[]', false, '2026-08-06T08:23:59.426246+00:00', '2026-08-11T12:08:44.169622+00:00', 'prijemna_premena', 'necvicaca', '[]', 'necvičiaca'),
    ('89958d12-db31-4dda-bccd-72f7035911c3', 2, 'Nastaviť systém', 'Spánok, frekvencia jedenia, lačnenie', 'Prvé tri zásady desatora — bez systému nefunguje nič ďalšie.', NULL, '[]', false, '2026-08-06T08:23:59.426246+00:00', '2026-08-11T12:08:44.169622+00:00', 'prijemna_premena', 'necvicaca', '["1. zásada — spánok", "2. zásada — frekvencia jedenia", "3. zásada — fyziologické načasovanie a lačnenie"]', 'necvičiaca'),
    ('39a397eb-08fd-407f-9f0e-9dd4e3598446', 3, 'Vyživiť telo', 'VMBTV koncept + generátor receptov', 'Ako jesť tak, aby telo dostalo všetko čo potrebuje — a ty si nekupovala nič navyše.', NULL, '[]', false, '2026-08-06T08:23:59.426246+00:00', '2026-08-11T12:08:44.169622+00:00', 'prijemna_premena', 'necvicaca', '["4. zásada — VMBTV koncept", "5. zásada — nekupovať potraviny navyše", "6. zásada — nejesť 3 dni mäso a mlieko"]', 'necvičiaca'),
    ('1e94e25e-af3c-4f17-a19a-760f226180aa', 4, 'Rozhýbať telo — rýchla chôdza a 10 000 krokov denne + pripraviť sa na cvičenie', 'Rýchla chôdza, 10 000 krokov denne a príprava na cvičenie', 'Prvý pohyb — bez cvičenia, len chôdza. Toto je motor prvých výsledkov. Následne sa pripravíš na cvičenie: rozcvičenie, správna technika DVP, diagnostika a budovanie návyku pravidelne cvičiť.', NULL, '[]', true, '2026-08-06T08:23:59.426246+00:00', '2026-08-11T12:08:44.169622+00:00', 'prijemna_premena', 'necvicaca', '["7. zásada — RCH 30 min/deň tempom < 9 min/km + 10 000 krokov denne"]', 'necvičiaca'),
    ('369d2b8d-1706-4514-a9de-690b0af2e0a6', 9, 'Získať KONDÍCIU a zvyšovať VO2max', 'Kondičné aktivity 2-3x za týždeň', 'Kondičné aktivity, ktoré rozvíjajú srdce, pľúca a vytrvalosť. VO2max je najsilnejší ukazovateľ biologického veku.', NULL, '[]', false, '2026-08-06T13:12:46.144448+00:00', '2026-09-13T16:06:21.046569+00:00', 'zivotna_premena', 'vykonnostna', '["10. zásada — vykonávaj 2-3x KA za týždeň a rozvíjaj VO2max"]', 'pokročilá až atlétka'),
    ('0cb4ba11-1484-47d0-9609-c78a4ec41bc2', 8, 'Získať SILU a zvyšovať % svalov', 'Silový tréning — BZS výzva II a III', 'Prechod na regulérny silový tréning: cvičenie s jednoručkami, potom s veľkou činkou. Rasteš na sile a zvyšuješ podiel svalovej hmoty.', NULL, '[]', false, '2026-08-06T08:23:59.426246+00:00', '2026-09-13T16:06:21.046569+00:00', 'zivotna_premena', 'vykonnostna', '["9. zásada — vykonávaj 2-3x ST za týždeň a zvyšuj % svalovej hmoty"]', 'pokročilá až atlétka'),
    ('de0cd5a2-dafe-42f0-b97c-65216f1b9a3b', 7, 'Odstrániť bolesti, získať mobilitu a flexibilitu', 'Joga, strečing, roller', 'Telo bez bolesti je telo, ktoré vydrží. Denných 30 minút mení všetko.', NULL, '[]', false, '2026-08-06T08:23:59.426246+00:00', '2026-09-13T16:06:21.046569+00:00', 'zivotna_premena', 'pripravna', '["8. zásada — vykonávaj každý deň 30 min (joga, strečing, roller)"]', 'začiatočníčka až mierne pokročilá'),
    ('5472fe36-86f2-4fa5-b572-c5b3ff7c5438', 5, 'Diagnostika techniky', 'Kontrola správneho prevedenia cvikov', 'Natoč sa pri cvičení, pošli video trénerovi a získaj spätnú väzbu na svoju techniku.', NULL, '[]', false, '2026-09-13T16:06:21.046569+00:00', '2026-09-13T16:06:21.046569+00:00', 'zivotna_premena', 'pripravna', '[]', 'kontrola techniky'),
    ('f4f38ca8-3f9f-480c-8ea8-a3c257399d84', 6, '90 dňová výzva', 'Praktická výzva a manuál PRÍJEMNÁ premena', 'Pozri si úvodné video, stiahni manuál a prejdi 90 dňovou výzvou.', NULL, '[]', false, '2026-09-13T16:06:21.046569+00:00', '2026-09-13T16:06:21.046569+00:00', 'zivotna_premena', 'pripravna', '[]', '90 dňová výzva'),
    ('35562274-15ae-4c76-a2b9-3284b2b4e647', 10, 'Žiť podľa DESATORO', 'Desať zásad pre život O DEKÁDU MLADŠIA', 'Osvoj si desať zásad a prenes ich do svojho každodenného života.', NULL, '[]', false, '2026-09-13T16:12:18.520002+00:00', '2026-09-13T20:26:42.201472+00:00', 'zivotna_premena', 'misia', '[]', 'cieľ cesty')
